def norm(s):
    return s.strip().replace("\r\n", "\n").replace("\\n", "\n")

def main():
    verifier = TranslationVerifier("dummy")
    # First validate all mappings internally
    norm_map = {}
    for orig, trans in COLOR_TAG_MAP.items():
        errs = verifier.validate_formatting_and_tags(orig, trans)
        if errs:
            raise ValueError(f"Mapping validation failed for '{orig}': {errs}")
        norm_map[norm(orig)] = (orig, trans)
    print(f"[OK] Pre-validation passed for all {len(COLOR_TAG_MAP)} mappings!")

    with open(CATALOG_PATH, "r", encoding="utf-8") as f:
        catalog = json.load(f)

    applied_count = 0
    for cat_name, entries in catalog["categories"].items():
        for entry in entries:
            orig = entry.get("original", "")
            orig_n = norm(orig)
            if orig_n in norm_map:
                _, trans_tmpl = norm_map[orig_n]
                # If original used literal \n (escaped), preserve that formatting
                if "\\n" in orig and "\n" not in orig:
                    entry["translation"] = trans_tmpl.replace("\r\n", "\\n").replace("\n", "\\n")
                else:
                    entry["translation"] = trans_tmpl
                applied_count += 1

    with open(CATALOG_PATH, "w", encoding="utf-8") as f:
        json.dump(catalog, f, ensure_ascii=False, indent=2)

    print(f"[Success] Applied {applied_count} color-tagged translations to {CATALOG_PATH}")

if __name__ == "__main__":
    main()
